tool_input.command:
cat > plan.json <<'E'
{
  "page": {
    "use": "page/basic",
    "data": {
      "title": "Checkout: shipping address",
      "site": "Checkout",
      "description": "Checkout, step 2 of 3: Shipping address.",
      "heading": "Checkout: shipping address"
    },
    "slots": {
      "main": [
        { "use": "nav/steps", "key": "progress", "data": { "label": "Checkout progress", "steps": [
          { "text": "Cart", "done": true },
          { "text": "Shipping", "current": "step" },
          { "text": "Payment" } ] } },
        { "use": "form/form", "key": "address", "data": { "label": "Shipping address" },
          "slots": {
            "fields": [
              { "use": "form/text-field", "key": "name", "data": { "label": "Full name", "name": "name", "autocomplete": "name", "required": true } },
              { "use": "form/text-field", "key": "line1", "data": { "label": "Address line 1", "name": "line1", "autocomplete": "address-line1", "required": true } },
              { "use": "form/text-field", "key": "line2", "data": { "label": "Address line 2 (optional)", "name": "line2", "autocomplete": "address-line2" } },
              { "use": "form/text-field", "key": "city", "data": { "label": "City", "name": "city", "autocomplete": "address-level2", "required": true } },
              { "use": "form/text-field", "key": "region", "data": { "label": "State or region", "name": "region", "autocomplete": "address-level1", "required": true } },
              { "use": "form/text-field", "key": "postal", "data": { "label": "Postal code", "name": "postal", "autocomplete": "postal-code", "required": true } },
              { "use": "form/select-field", "key": "country", "data": { "label": "Country", "name": "country", "required": true, "options": [
                { "value": "us", "label": "United States" }, { "value": "ca", "label": "Canada" }, { "value": "mx", "label": "Mexico" } ] } },
              { "use": "form/text-field", "key": "phone", "data": { "label": "Phone", "name": "phone", "type": "tel", "autocomplete": "tel", "required": true, "hint": "For the courier" } },
              { "use": "form/checkbox", "key": "billing", "data": { "label": "Billing address is the same", "name": "billing-same" } },
              { "use": "form/choice-group", "key": "speed", "data": { "legend": "Shipping speed", "name": "speed", "required": true, "choices": [
                { "value": "standard", "label": "Standard, 5–7 days, free" },
                { "value": "express", "label": "Express, 2 days, $12" } ] } }
            ],
            "actions": [
              { "use": "action/submit", "key": "continue", "data": { "label": "Continue to payment" } },
              { "use": "action/link-button", "key": "back", "data": { "label": "Back to cart", "href": "/cart", "variant": "ghost" } }
            ]
          } },
        { "use": "content/section", "key": "summary", "data": { "title": "Order summary" }, "slots": { "body": [
          { "use": "data/description-list", "key": "items", "data": { "items": [
            { "term": "Ridgeline 40 L × 1", "description": "$189" },
            { "term": "Shipping", "description": "$0" },
            { "term": "Total", "description": "$189" } ] } } ] } }
      ]
    }
  }
}
E
